const std = @import("std");

pub fn main() !void {
    const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    const data = [_]u8{ 0x48, 0x65, 0x6C, 0x6C, 0x6F };

    var i: usize = 0;
    while (i < data.len) {
        const b0 = data[i];
        const b1 = if (i + 1 < data.len) data[i + 1] else 0;
        const b2 = if (i + 2 < data.len) data[i + 2] else 0;

        const idx0 = b0 >> 2;
        const idx1 = ((b0 & 0x03) << 4) | (b1 >> 4);
        const idx2 = ((b1 & 0x0F) << 2) | (b2 >> 6);
        const idx3 = b2 & 0x3F;

        std.debug.print("{c}{c}", .{alphabet[idx0], alphabet[idx1]});
        std.debug.print("{c}{c}", .{alphabet[idx2], alphabet[idx3]});
        i += 3;
    }
    std.debug.print("\n", .{});
}
